import{_ as e,o as s,c as i,a0 as t}from"./chunks/framework.DCluYYrN.js";const k=JSON.parse('{"title":"模組 WebUI","description":"","frontmatter":{},"headers":[],"relativePath":"zh_TW/guide/module-webui.md","filePath":"zh_TW/guide/module-webui.md"}'),n={name:"zh_TW/guide/module-webui.md"};function p(r,a,l,o,h,c){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="module-webui" tabindex="-1">模組 WebUI <a class="header-anchor" href="#module-webui" aria-label="Permalink to &quot;模組 WebUI {#module-webui}&quot;">​</a></h1><p>KernelSU 的模組除了執行啟動腳本和修改系統檔案之外，還支援顯示 UI 介面和與使用者互動。</p><p>該模組可以透過任何 Web 技術編寫 HTML + CSS + JavaScript 頁面。 KernelSU的管理器將透過 WebView 顯示這些頁面。它還提供了一些用於與系統互動的 JavaScript API，例如執行 shell 命令。</p><h2 id="webroot-directory" tabindex="-1">WebUI 根目錄 <a class="header-anchor" href="#webroot-directory" aria-label="Permalink to &quot;WebUI 根目錄 {#webroot-directory}&quot;">​</a></h2><p>Web資源應放置在模組根目錄的 <code>webroot</code> 子目錄中，並且其中<strong>必須</strong>有一個名為 <code>index.html</code> 的文件，該檔案是模組頁面入口。</p><p>包含Web介面的最簡單的模組結構如下：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❯ tree .</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>|-- module.prop</span></span>
<span class="line"><span>\`-- webroot</span></span>
<span class="line"><span>    \`-- index.html</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">提醒</p><p>安裝模組時，KernelSU 將自動設定<code>webroot</code>的權限和 SELinux context。如果您不知道自己在做什麼，請不要自行設定該目錄的權限！</p></div><p>如果您的頁面包含 CSS 和 JavaScript，您也需要將其放入此目錄中。</p><h2 id="javascript-api" tabindex="-1">JavaScript API <a class="header-anchor" href="#javascript-api" aria-label="Permalink to &quot;JavaScript API&quot;">​</a></h2><p>如果只是一個顯示頁面，那和一般網頁沒有什麼不同。更重要的是，KernelSU 提供了一系列的系統 API，讓您可以實現模組獨特的功能。</p><p>KernelSU <a href="https://www.npmjs.com/package/kernelsu" target="_blank" rel="noreferrer">在 npm 上發布</a>了一個 JavaScript 庫，您可以在網頁的 JavaScript 程式碼中使用它。</p><p>例如，您可以執行 shell 命令來取得特定配置或修改屬性：</p><div class="language-JavaScript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">JavaScript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { exec } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;kernelsu&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">errno</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">stdout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> exec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;getprop ro.product.model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>再例如，你可以讓網頁全螢幕顯示，或是顯示一個 Toast。</p><p><a href="https://www.npmjs.com/package/kernelsu" target="_blank" rel="noreferrer">API 文檔</a></p><p>如果您發現現有的 API 無法滿足您的需求或使用不方便，歡迎您在<a href="https://github.com/tiann/KernelSU/issues" target="_blank" rel="noreferrer">這裡</a>給我們建議！</p><h2 id="some-tips" tabindex="-1">一些技巧 <a class="header-anchor" href="#some-tips" aria-label="Permalink to &quot;一些技巧 {#some-tips}&quot;">​</a></h2><ol><li>您可以正常使用 <code>localStorage</code> 來儲存一些數據，但解除安裝管理器後，這些數據將會遺失。如果需要持久保存，可以自行將資料寫入某個目錄。</li><li>對於簡單的頁面，我建議您使用 <a href="https://parceljs.org/" target="_blank" rel="noreferrer">parceljs</a> 進行打包。它無須設定，使用非常方便。不過，如果你是前端高手或有自己的喜好，那就選擇你喜歡的吧！</li></ol>`,19)])])}const u=e(n,[["render",p]]);export{k as __pageData,u as default};
